		oPpg.AddParameter3("chkposy", siBool, 1,null,null,false);
		oPpg.AddParameter3("chkposz", siBool, 1,null,null,false);
		oPpg.AddParameter3("chkrotx", siBool, 1,null,null,false);
		oPpg.AddParameter3("chkroty", siBool, 1,null,null,false);
		oPpg.AddParameter3("chkrotz", siBool, 1,null,null,false);


